import random,subprocess,re
R=b'\x1b[0m'; common={b'\x1b[31m',b'\x1b[32m'}
def extract(data):
 # Output line after prefix: recover token marks from basic vs refined styles.
 result=[]
 for ln in data.splitlines()[1:]:
  parts=ln.split(R)
  marks=[]
  for i in range(3,len(parts),2):
   seg=parts[i]
   if not seg:continue
   codes=re.match(br'(?:\x1b\[[0-9;]*m)*',seg)[0]
   text=seg[len(codes):]
   marks += [codes in common]*len(text)
  result.append(marks)
 return result

def lcs(a,b,prefix=False,suffix=False,tie=True):
 n=len(a);m=len(b);res_a=[False]*n;res_b=[False]*m
 lo=0
 if prefix:
  while lo<min(n,m) and a[lo]==b[lo]:
   res_a[lo]=res_b[lo]=True;lo+=1
 hi_a=n;hi_b=m
 if suffix:
  while hi_a>lo and hi_b>lo and a[hi_a-1]==b[hi_b-1]:
   hi_a-=1;hi_b-=1;res_a[hi_a]=res_b[hi_b]=True
 dp=[[0]*(hi_b+1) for _ in range(hi_a+1)]
 for i in range(hi_a-1,lo-1,-1):
  for j in range(hi_b-1,lo-1,-1):
   dp[i][j] = 1+dp[i+1][j+1] if a[i]==b[j] else max(dp[i+1][j],dp[i][j+1])
 i=j=lo
 while i<hi_a and j<hi_b:
  if a[i]==b[j]:res_a[i]=res_b[j]=True;i+=1;j+=1
  elif dp[i][j+1]>dp[i+1][j] or (tie and dp[i][j+1]==dp[i+1][j]):j+=1
  else:i+=1
 return [res_a,res_b]

def main():
 random.seed(4984)
 cases=[('!@','@!'),('!@!','@!@')]+[(''.join(random.choices('!@#$%',k=random.randint(1,12))),''.join(random.choices('!@#$%',k=random.randint(1,12)))) for _ in range(500)]
 data=''.join('@@\n-'+a+'\n+'+b+'\n' for a,b in cases)
 proc=subprocess.run(['./executable'],input=data.encode(),capture_output=True)
 outputs=proc.stdout.split(R+b'@@'+R+b'\n')[1:]
 opts=[(p,s,t) for p in [False,True] for s in [False,True] for t in [False,True]]
 errors={o:[] for o in opts}
 for (a,b),out in zip(cases,outputs):
  actual=extract(b'header\n'+out)
  for opt in opts:
   predicted=[x[:-1] for x in lcs(a+'\n',b+'\n',*opt)]
   if actual!=predicted:
    errors[opt].append((a,b,actual,predicted))
 for o,errs in errors.items():
  print(o,'mismatches',len(errs))
  for a,b,real,pred in errs[:4]:
   print(repr(a),repr(b),'obs',real,'pred',pred)
if __name__=='__main__':main()
