#!/usr/bin/env python3
"""A byte-preserving unified-diff renderer with token-level highlighting."""
import re
import sys
import unicodedata
from pathlib import Path

RESET = b'\x1b[0m'
ASCII_SPACE = b' \t\r\n\x0c'
VERSION = 'diffr 0.1.5\n'
FACES = ('added', 'refine-added', 'removed', 'refine-removed')
ATTR_NAMES = ('foreground|background|italic|noitalic|bold|nobold|dimmed|nodimmed|'
              'intense|nointense|underline|nounderline|none')
COLOR_NAMES = ('black', 'red', 'green', 'yellow', 'blue', 'magenta', 'cyan', 'white')
COLOR_CHOICES = 'black, blue, green, red, cyan, magenta, yellow, white'


class UserError(Exception):
    def __init__(self, message, status=255):
        super().__init__(message)
        self.status = status


def help_text(long=False):
    name = 'LONG_HELP' if long else 'SHORT_HELP'
    if name in globals():
        return globals()[name]
    filename = 'help.txt' if long else 'h.txt'
    return (Path(__file__).parent / 'assets' / filename).read_text().replace('$VERSION', '0.1.5')


class Face:
    def __init__(self, fg=None, bg=None, bold=False):
        self.fg = fg
        self.bg = bg
        self.bold = bold
        self.italic = self.dimmed = self.intense = self.underline = False

    def clear(self):
        self.__init__()

    def ansi(self):
        s = RESET
        for flag, code in [('bold', 1), ('dimmed', 2), ('italic', 3), ('underline', 4)]:
            if getattr(self, flag):
                s += ('\x1b[%dm' % code).encode()
        for color, bg in [(self.fg, False), (self.bg, True)]:
            if color is None:
                continue
            kind, value = color
            code = 48 if bg else 38
            if kind == 'rgb':
                s += ('\x1b[%d;2;%d;%d;%dm' % (code, *value)).encode()
            elif kind == 'index':
                s += ('\x1b[%d;5;%dm' % (code, value)).encode()
            elif self.intense:
                s += ('\x1b[%d;5;%dm' % (code, value + 8)).encode()
            else:
                s += ('\x1b[%dm' % ((40 if bg else 30) + value)).encode()
        return s


def default_faces():
    return {'added': Face(('name', 2)), 'removed': Face(('name', 1)),
            'refine-added': Face(('rgb', (255, 255, 255)), ('name', 2), True),
            'refine-removed': Face(('rgb', (255, 255, 255)), ('name', 1), True)}


def byte_number(text):
    if text.startswith('0x'):
        digits, base, pattern = text[2:], 16, r'\+?[0-9a-fA-F]+'
    else:
        digits, base, pattern = text, 10, r'\+?[0-9]+'
    if not re.fullmatch(pattern, digits):
        return None
    value = int(digits, base)
    return value if value <= 255 else None


def parse_color(text):
    if text == 'none':
        return None
    if text.lower() in COLOR_NAMES:
        return 'name', COLOR_NAMES.index(text.lower())
    if ',' in text:
        nums = [byte_number(x) for x in text.split(',')]
        if len(nums) == 3 and all(x is not None for x in nums):
            return 'rgb', tuple(nums)
        raise UserError("unexpected color value: unrecognized RGB color triple, should be "
                        "'[0-255],[0-255],[0-255]' (or a hex triple), but is '%s'\n" % text)
    value = byte_number(text)
    if value is not None:
        return 'index', value
    if re.fullmatch('[0-9A-Fa-f]*', text):
        raise UserError("unexpected color value: unrecognized ansi256 color number, should be "
                        "'[0-255]' (or a hex number), but is '%s'\n" % text)
    raise UserError("unexpected color value: unrecognized color name '%s'. Choose from: %s\n" %
                    (text, COLOR_CHOICES))


