    pieces = spec.split(':')
    name = pieces[0]
    if name not in faces:
        raise UserError("unexpected face name: got '%s', expected %s\n" % (name, '|'.join(FACES)))
    face = faces[name]
    i = 1
    while i < len(pieces):
        attr = pieces[i]
        i += 1
        if attr in ('foreground', 'background'):
            if i == len(pieces):
                raise UserError("error parsing color: missing color value for face '%s'\n" % name)
            color = parse_color(pieces[i])
            i += 1
            setattr(face, 'fg' if attr == 'foreground' else 'bg', color)
        elif attr == 'none':
            face.clear()
        elif attr in ('italic', 'bold', 'dimmed', 'intense', 'underline'):
            setattr(face, attr, True)
        elif attr.startswith('no') and attr[2:] in ('italic', 'bold', 'dimmed', 'intense', 'underline'):
            setattr(face, attr[2:], False)
        else:
            raise UserError("unexpected attribute name: got '%s', expected %s\n" % (attr, ATTR_NAMES))


