    faces = default_faces()
    numbers = None
    i = 0
    while i < len(args):
        arg = args[i]
        i += 1
        if arg in ('-h', '--help'):
            sys.stdout.write(help_text(arg == '--help'))
            return None
        if arg in ('-V', '--version'):
            sys.stderr.write(VERSION)
            return None
        if arg == '--colors':
            if i == len(args):
                raise UserError("option requires an argument: '--colors'\n", 2)
            apply_spec(faces, args[i])
            i += 1
        elif arg == '--line-numbers':
            numbers = args[i] if i < len(args) else 'compact'
            if i < len(args):
