    """Words, horizontal whitespace, CRLF, and individual other characters."""
    text = data.decode('utf-8', 'surrogateescape')
    result = []
    i = 0
    while i < len(text):
        j = i + 1
        if word_char(text[i]):
            while j < len(text) and word_char(text[j]):
                j += 1
        elif text[i] in ' \t':
            while j < len(text) and text[j] in ' \t':
                j += 1
        elif text[i] == '\r' and j < len(text) and text[j] == '\n':
            j += 1
        result.append(text[i:j].encode('utf-8', 'surrogateescape'))
        i = j
    return result


